package br.com.tapeteskalke.entity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.time.ZoneOffset; import lombok.Getter; import lombok.Setter;
// Linha da ficha técnica: quantidade de uma matéria-prima usada em UMA unidade do produto acabado.
@Entity @Table(name="produto_componente") @Getter @Setter public class ProdutoComponente { @Id @Column(length=38) private String id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="id_produto",nullable=false) private Produto produto; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="id_materia_prima",nullable=false) private Produto materiaPrima; @Column(nullable=false,precision=15,scale=3) private BigDecimal quantidade; @Column(name="created_at",nullable=false,updatable=false) private OffsetDateTime createdAt; @PrePersist void criar(){if(id==null)id=java.util.UUID.randomUUID().toString();if(createdAt==null)createdAt=OffsetDateTime.now(ZoneOffset.UTC);} }
